import java.util.Scanner;
public class JBooleanDryHot2 {
	public static void main(String[] args) {
		//Khatwa 1: Iqra madakhil al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhul ma ida kana al-jaw haran jiddan (true aw false):");
		boolean tooHot = scan.nextBoolean();	
		System.out.println("Adkhul ma ida kana al-jaw jaf jiddan (true aw false):");
		boolean tooDry = scan.nextBoolean();		
		scan.close();
		//Khatwa 2: Uktub ta'bir boolean li-tahdid in kana hara aw jaff (aw kilahuma)
		boolean value = tooHot || tooDry;
		System.out.println(value);
	}
}
